  function t(clave, idioma, vars) {
    var dic = idioma === 'en' ? EN : ES, v = dic[clave];
    if (v === undefined) { if (idioma === 'en' && faltantes.indexOf(clave) < 0) faltantes.push(clave); v = ES[clave]; }
    if (v === undefined) return clave;
    if (typeof v !== 'string') return v;
    return v.replace(/\{(\w+)\}/g, function (m, k) { return vars && vars[k] !== undefined && vars[k] !== null ? String(vars[k]) : m; });
  }

  // Formato numérico según idioma: coma decimal en español.
  function num(v, dec, idioma) {
    if (v === null || v === undefined || !isFinite(v)) return idioma === 'en' ? 'n/a' : 'n. d.';
    var s = Number(v).toFixed(dec === undefined ? 2 : dec);
    if (s === '-0' || /^-0\.0*$/.test(s)) s = s.slice(1);
    var partes = s.split('.'), ent = partes[0].replace(/\B(?=(\d{3})+(?!\d))/g, idioma === 'en' ? ',' : ' ');
    if (idioma !== 'en') ent = ent.replace(/ /g, ' ');
    s = ent + (partes[1] ? (idioma === 'en' ? '.' : ',') + partes[1] : '');
    return s;
  }

  function claves(idioma) { return Object.keys(idioma === 'en' ? EN : ES); }

  return { t: t, num: num, ES: ES, EN: EN, claves: claves, faltantes: faltantes };
